<style>
:root{
  --primary:#1A3A6E;
  --primary-light:#1E90FF;
  --primary-dark:#1565C0;
  --accent:#F5A623;
  --bg-soft:#F4F8FC;
  --bg-white:#FFFFFF;
  --text-dark:#1A2B4A;
  --text-muted:#5A6B85;
  --border:#E1E8F0;
  --shadow-sm:0 2px 8px rgba(26,58,110,.06);
  --shadow-md:0 6px 20px rgba(26,58,110,.10);
  --shadow-lg:0 12px 32px rgba(26,58,110,.15);
}
*{margin:0;padding:0;box-sizing:border-box}
body{font-family:'Poppins',sans-serif;background:var(--bg-soft);color:var(--text-dark);line-height:1.6;font-size:14px}
.container{max-width:1240px;margin:0 auto;padding:0 20px}

/* ========== HERO ========== */
.tour-hero{
  position:relative;
  margin-bottom:40px;
}

.hero-image{
  position:relative;
  height:520px;
  border-radius:0 0 30px 30px;
  overflow:hidden;
  background:var(--primary);
}

.hero-image img{
  width:100%;
  height:100%;
  object-fit:cover;
  display:block;
}

.hero-overlay{
  position:absolute;
  inset:0;
  background:linear-gradient(
    to top,
    rgba(0,0,0,.68),
    rgba(0,0,0,.28),
    rgba(0,0,0,.12)
  );
  pointer-events:none;
}

.hero-title-wrap{
  position:absolute;
  left:50%;
  bottom:120px;
  transform:translateX(-50%);
  width:100%;
  max-width:1240px;
  padding:0 20px;
  z-index:2;
  color:#fff;
}

.hero-badge{
  display:inline-flex;
  align-items:center;
  gap:8px;
  background:rgba(255,255,255,.16);
  backdrop-filter:blur(10px);
  padding:8px 16px;
  border-radius:30px;
  color:#fff;
  font-size:12px;
  font-weight:500;
  width:fit-content;
  margin-bottom:18px;
  border:1px solid rgba(255,255,255,.22);
}

.hero-badge i{color:var(--accent)}

.hero-title-wrap h1{
  font-family:'Playfair Display',serif;
  font-size:48px;
  line-height:1.15;
  color:#fff;
  max-width:880px;
  font-weight:700;
  text-shadow:0 4px 18px rgba(0,0,0,.35);
}

/* Hero details under image */
.hero-info-card{
  max-width:1180px;
  margin:-55px auto 0;
  background:#fff;
  border-radius:22px;
  padding:24px;
  position:relative;
  z-index:5;
  box-shadow:0 12px 35px rgba(26,58,110,.12);
  border:1px solid var(--border);
}

.hero-meta{
  display:grid;
  grid-template-columns:repeat(4,1fr);
  gap:18px;
}

.hero-meta-item{
  display:flex;
  align-items:center;
  gap:14px;
  padding:14px;
  border-radius:14px;
  background:#f8fbff;
  border:1px solid #eef4fb;
}

.hero-meta-item i{
  width:48px;
  height:48px;
  border-radius:50%;
  background:linear-gradient(135deg,var(--primary),var(--primary-light));
  color:#fff;
  display:flex;
  align-items:center;
  justify-content:center;
  font-size:18px;
  flex-shrink:0;
}

.hero-meta-item span{
  display:block;
  font-size:11px;
  text-transform:uppercase;
  color:var(--text-muted);
  margin-bottom:3px;
  letter-spacing:.5px;
  font-weight:500;
}

.hero-meta-item strong{
  font-size:14px;
  color:var(--text-dark);
  font-weight:700;
}

/* Layout */
.booking-wrapper{padding:32px 0 50px}
.booking-grid{display:grid;grid-template-columns:1fr 380px;gap:24px;align-items:start}

/* Main Content */
.main-content{background:#fff;border-radius:14px;box-shadow:var(--shadow-sm);overflow:hidden}
.tabs{display:flex;border-bottom:1px solid var(--border);background:#fafbfd;padding:0 8px}
.tab{padding:13px 16px;font-size:13px;font-weight:600;color:var(--text-muted);
  cursor:pointer;border-bottom:3px solid transparent;transition:all .25s;
  display:flex;align-items:center;gap:7px;white-space:nowrap}
.tab i{font-size:13px}
.tab.active{color:var(--primary);border-bottom-color:var(--primary-light);background:#fff}
.tab:hover:not(.active){color:var(--primary-dark)}
.tab-panel{display:none;padding:24px 28px}
.tab-panel.active{display:block;animation:fadeIn .3s ease}
@keyframes fadeIn{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}

.section-title{font-family:'Playfair Display',serif;font-size:20px;font-weight:700;
  color:var(--primary);margin-bottom:8px;display:flex;align-items:center;gap:10px}
.section-title::before{content:'';width:4px;height:20px;background:var(--primary-light);
  border-radius:2px}
.section-sub{color:var(--text-muted);font-size:13px;margin-bottom:18px;line-height:1.7}

/* Quick Facts */
.quick-facts{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:22px}
.fact-card{background:linear-gradient(135deg,var(--bg-soft),#fff);border:1px solid var(--border);
  border-radius:10px;padding:14px;text-align:center;transition:all .25s}
.fact-card:hover{transform:translateY(-2px);border-color:var(--primary-light);box-shadow:var(--shadow-sm)}
.fact-icon{width:38px;height:38px;border-radius:50%;background:var(--primary);color:#fff;
  display:flex;align-items:center;justify-content:center;margin:0 auto 8px;font-size:14px}
.fact-label{font-size:10px;color:var(--text-muted);text-transform:uppercase;letter-spacing:.5px;
  margin-bottom:3px;font-weight:500}
.fact-value{font-size:12px;font-weight:600;color:var(--text-dark)}

/* ========== ROUTE BAR ========== */
.route-section{margin-bottom:18px}
.route-bar{
  background:linear-gradient(135deg,var(--primary) 0%,var(--primary-dark) 100%);
  border-radius:12px;padding:24px 20px;position:relative;overflow:hidden;
  box-shadow:var(--shadow-md)
}
.route-bar::before{content:'';position:absolute;top:-30px;right:-30px;width:120px;height:120px;
  background:rgba(255,255,255,.05);border-radius:50%;pointer-events:none}
.route-bar::after{content:'';position:absolute;bottom:-40px;left:-40px;width:140px;height:140px;
  background:rgba(245,166,35,.08);border-radius:50%;pointer-events:none}
.route-track{
  display:flex;align-items:flex-start;justify-content:space-between;
  position:relative;z-index:2;gap:8px;flex-wrap:nowrap
}
.route-stop{
  display:flex;flex-direction:column;align-items:center;gap:8px;
  flex:1 1 0;min-width:0;text-align:center
}
.route-stop-icon{
  width:46px;height:46px;border-radius:50%;background:#fff;
  display:flex;align-items:center;justify-content:center;
  font-size:18px;color:var(--primary);
  box-shadow:0 4px 12px rgba(0,0,0,.15);
  border:3px solid var(--accent);
  transition:all .3s;
  flex-shrink:0
}
.route-stop:hover .route-stop-icon{transform:scale(1.1) rotate(-5deg)}
.route-stop-name{color:#fff;font-weight:600;font-size:13px;letter-spacing:.3px}
.route-stop-num{color:var(--accent);font-size:10px;font-weight:500;text-transform:uppercase;letter-spacing:1px}
.route-line{
  flex:0 0 auto;width:40px;height:2px;
  background:repeating-linear-gradient(to right,rgba(255,255,255,.4) 0 6px,transparent 6px 12px);
  position:relative;
  margin-top:23px;
  align-self:flex-start
}
.route-line i{
  position:absolute;top:50%;left:50%;
  transform:translate(-50%,-50%);
  color:var(--accent);font-size:11px;
  background:var(--primary);
  width:22px;height:22px;
  border-radius:50%;
  display:flex;align-items:center;justify-content:center;
  border:2px solid rgba(255,255,255,.2)
}

/* Itinerary */
.timeline{position:relative;padding-left:28px}
.timeline::before{content:'';position:absolute;left:10px;top:8px;bottom:8px;width:2px;
  background:linear-gradient(to bottom,var(--primary-light),var(--primary),var(--primary-dark))}
.day-item{position:relative;padding-bottom:14px}
.day-item:last-child{padding-bottom:0}
.day-marker{position:absolute;left:-28px;top:6px;width:22px;height:22px;border-radius:50%;
  background:#fff;border:3px solid var(--primary-light);display:flex;align-items:center;
  justify-content:center;font-size:10px;font-weight:700;color:var(--primary);z-index:1}
.day-header{background:#fafbfd;border:1px solid var(--border);border-radius:10px;padding:11px 14px;
  display:flex;justify-content:space-between;align-items:center;transition:all .25s;cursor:pointer}
.day-header:hover{border-color:var(--primary-light);background:#fff}
.day-item.open .day-header{background:#fff;border-color:var(--primary-light);box-shadow:var(--shadow-sm);
  border-radius:10px 10px 0 0}
.day-title{font-weight:600;color:var(--text-dark);font-size:13px}
.day-title span{color:var(--primary);margin-right:8px}
.day-toggle{color:var(--primary);font-size:11px;transition:transform .3s}
.day-item.open .day-toggle{transform:rotate(180deg)}
.day-content{max-height:0;overflow:hidden;transition:max-height .35s ease;
  background:#fff}
.day-item.open .day-content{max-height:300px;padding:12px 14px;border:1px solid var(--primary-light);
  border-top:none;border-radius:0 0 10px 10px}
.day-content p{color:var(--text-muted);font-size:13px;line-height:1.7}

/* ========== INCLUSIONS - TRAVEL TICKET DESIGN ========== */
.inc-wrapper{position:relative;padding:8px 0 4px}

.inc-intro{text-align:center;margin-bottom:26px;position:relative}
.inc-intro-label{
  display:inline-block;font-size:10px;font-weight:600;letter-spacing:3px;
  color:var(--accent);text-transform:uppercase;margin-bottom:8px;
  padding:4px 14px;background:rgba(245,166,35,.1);border-radius:20px
}
.inc-intro h2{
  font-family:'Playfair Display',serif;font-size:24px;
  color:var(--primary);margin-bottom:6px;font-weight:700
}
.inc-intro p{color:var(--text-muted);font-size:13px;max-width:520px;margin:0 auto}

.ticket-container{position:relative;display:grid;gap:18px}

.ticket{
  position:relative;background:#fff;border-radius:14px;overflow:hidden;
  box-shadow:0 8px 28px rgba(26,58,110,.10),0 2px 6px rgba(26,58,110,.06);
  display:grid;grid-template-columns:90px 1fr;
  transition:transform .35s ease,box-shadow .35s ease
}
.ticket:hover{
  transform:translateY(-3px);
  box-shadow:0 14px 36px rgba(26,58,110,.14),0 4px 10px rgba(26,58,110,.08)
}

.ticket-stub{
  position:relative;display:flex;flex-direction:column;
  align-items:center;justify-content:center;gap:10px;
  padding:20px 8px;color:#fff;overflow:hidden
}
.ticket.included .ticket-stub{
  background:linear-gradient(160deg,#15803d 0%,#16a34a 50%,#22c55e 100%)
}
.ticket.excluded .ticket-stub{
  background:linear-gradient(160deg,#991b1b 0%,#b91c1c 50%,#dc2626 100%)
}
.ticket-stub::before{
  content:'';position:absolute;inset:0;
  background-image:
    radial-gradient(circle at 20% 10%,rgba(255,255,255,.12) 1px,transparent 1.5px),
    radial-gradient(circle at 80% 30%,rgba(255,255,255,.08) 1px,transparent 1.5px),
    radial-gradient(circle at 30% 70%,rgba(255,255,255,.10) 1px,transparent 1.5px),
    radial-gradient(circle at 70% 90%,rgba(255,255,255,.08) 1px,transparent 1.5px);
  background-size:60px 60px;pointer-events:none
}
.stub-icon{
  width:46px;height:46px;border-radius:50%;
  background:rgba(255,255,255,.18);
  border:2px solid rgba(255,255,255,.35);
  backdrop-filter:blur(8px);
  display:flex;align-items:center;justify-content:center;
  font-size:18px;position:relative;z-index:2;
  box-shadow:inset 0 0 14px rgba(0,0,0,.1)
}
.stub-label{
  writing-mode:vertical-rl;transform:rotate(180deg);
  font-size:9px;font-weight:700;letter-spacing:4px;
  text-transform:uppercase;opacity:.85;
  position:relative;z-index:2
}
.stub-count{
  position:relative;z-index:2;
  background:rgba(0,0,0,.18);
  padding:3px 8px;border-radius:10px;
  font-size:10px;font-weight:700;letter-spacing:.5px;
  border:1px solid rgba(255,255,255,.15)
}

.ticket-perf{position:absolute;top:0;bottom:0;left:90px;width:0;z-index:3;pointer-events:none}
.ticket-perf::before,.ticket-perf::after{
  content:'';position:absolute;left:50%;
  transform:translateX(-50%);
  width:14px;height:14px;border-radius:50%;
  background:#fff;
  box-shadow:inset 0 0 0 1px var(--border)
}
.ticket-perf::before{top:-7px}
.ticket-perf::after{bottom:-7px}
.ticket-perf .dots{
  position:absolute;top:14px;bottom:14px;left:50%;
  transform:translateX(-50%);width:1px;
  background-image:linear-gradient(to bottom,var(--border) 50%,transparent 50%);
  background-size:1px 7px;background-repeat:repeat-y
}

.ticket-body{padding:18px 22px 18px 28px;position:relative}
.ticket-header-row{
  display:flex;justify-content:space-between;align-items:flex-start;
  margin-bottom:14px;padding-bottom:12px;
  border-bottom:1px dashed var(--border)
}
.ticket-title{
  font-family:'Playfair Display',serif;
  font-size:17px;font-weight:700;line-height:1.2
}
.ticket.included .ticket-title{color:#15803d}
.ticket.excluded .ticket-title{color:#991b1b}
.ticket-subtitle{
  font-size:10px;color:var(--text-muted);margin-top:3px;
  letter-spacing:.5px;text-transform:uppercase;font-weight:500
}

.ticket-stamp{
  flex-shrink:0;width:54px;height:54px;border-radius:50%;
  display:flex;align-items:center;justify-content:center;
  font-family:'Playfair Display',serif;
  font-size:9px;font-weight:700;letter-spacing:1.5px;
  text-align:center;line-height:1.1;text-transform:uppercase;
  position:relative;transform:rotate(-12deg);opacity:.85
}
.ticket.included .ticket-stamp{border:2px solid #15803d;color:#15803d}
.ticket.excluded .ticket-stamp{border:2px solid #991b1b;color:#991b1b}
.ticket-stamp::before{
  content:'';position:absolute;inset:3px;border-radius:50%;
  border:1px dashed currentColor;opacity:.5
}
.ticket-stamp span{position:relative;z-index:1}

.ticket-items{display:grid;grid-template-columns:1fr 1fr;gap:8px 16px}
.ticket-item{
  display:flex;align-items:flex-start;gap:9px;
  font-size:12.5px;color:var(--text-dark);
  line-height:1.5;padding:3px 0
}
.ticket-item-icon{
  flex-shrink:0;width:18px;height:18px;border-radius:50%;
  display:flex;align-items:center;justify-content:center;
  font-size:9px;margin-top:2px;font-weight:900
}
.ticket.included .ticket-item-icon{background:#dcfce7;color:#15803d}
.ticket.excluded .ticket-item-icon{background:#fee2e2;color:#991b1b}
.ticket-item-text{flex:1}

.ticket-footer{
  margin-top:14px;padding-top:12px;
  border-top:1px dashed var(--border);
  display:flex;justify-content:space-between;align-items:center
}
.ticket-meta{
  font-size:9px;color:var(--text-muted);
  letter-spacing:1.5px;text-transform:uppercase;
  font-weight:600;font-family:'Courier New',monospace
}
.ticket-barcode{display:flex;align-items:center;gap:1px;height:18px}
.ticket-barcode span{display:block;width:1.5px;background:var(--text-dark);opacity:.7}
.ticket-barcode span:nth-child(1){height:60%}
.ticket-barcode span:nth-child(2){height:100%;width:2.5px}
.ticket-barcode span:nth-child(3){height:80%}
.ticket-barcode span:nth-child(4){height:100%;width:1px}
.ticket-barcode span:nth-child(5){height:50%;width:2.5px}
.ticket-barcode span:nth-child(6){height:100%}
.ticket-barcode span:nth-child(7){height:70%;width:1px}
.ticket-barcode span:nth-child(8){height:100%;width:3px}
.ticket-barcode span:nth-child(9){height:60%}
.ticket-barcode span:nth-child(10){height:100%}
.ticket-barcode span:nth-child(11){height:80%;width:2px}
.ticket-barcode span:nth-child(12){height:100%}

/* ========== Sidebar Booking ========== */
.booking-sidebar{position:sticky;top:20px;z-index:1}
.price-card{
  background:#fff;border-radius:14px;
  box-shadow:var(--shadow-md);overflow:hidden;
  border:1px solid var(--border);
  position:relative;
  z-index:2
}
.price-header{background:linear-gradient(135deg,var(--primary),var(--primary-dark));
  color:#fff;padding:18px;text-align:center;position:relative;overflow:hidden}
.price-header::before{content:'';position:absolute;top:-30px;right:-30px;width:120px;height:120px;
  background:rgba(255,255,255,.05);border-radius:50%}
.price-label{font-size:11px;opacity:.85;text-transform:uppercase;letter-spacing:1px;margin-bottom:5px}
.price-amount{font-family:'Playfair Display',serif;font-size:34px;font-weight:700;line-height:1}
.price-amount small{font-size:14px;font-weight:400;opacity:.8}
.price-per{font-size:11px;opacity:.8;margin-top:4px}
.price-body{padding:18px;position:relative;background:#fff}

.form-group{margin-bottom:12px;min-width:0;position:relative}
.form-label{font-size:11px;font-weight:600;color:var(--text-dark);margin-bottom:5px;
  display:flex;align-items:center;gap:6px;text-transform:uppercase;letter-spacing:.3px}
.form-label i{color:var(--primary-light);font-size:11px}
.form-input,.form-select{width:100%;padding:9px 11px;border:1px solid var(--border);
  border-radius:7px;font-size:13px;font-family:inherit;color:var(--text-dark);
  background:#fafbfd;transition:all .2s;position:relative}
.form-input:focus,.form-select:focus{outline:none;border-color:var(--primary-light);
  background:#fff;box-shadow:0 0 0 3px rgba(30,144,255,.1)}
textarea.form-input{resize:vertical;min-height:60px}
.form-row{display:grid;grid-template-columns:1fr 1fr;gap:9px}

/* ========== COUNTER ========== */
.counter-wrap{
  display:flex !important;
  align-items:center !important;
  justify-content:space-between !important;
  background:#fafbfd !important;
  border:1px solid var(--border) !important;
  border-radius:7px !important;
  padding:3px !important;
  gap:4px !important;
  width:100% !important;
  min-height:38px !important;
  box-sizing:border-box !important;
  position:relative !important
}
.counter-btn{
  width:32px !important;
  height:32px !important;
  min-width:32px !important;
  border:none !important;
  background:var(--primary) !important;
  color:#fff !important;
  border-radius:5px !important;
  cursor:pointer !important;
  font-size:18px !important;
  font-weight:700 !important;
  line-height:1 !important;
  display:flex !important;
  align-items:center !important;
  justify-content:center !important;
  flex-shrink:0 !important;
  font-family:inherit !important;
  padding:0 !important;
  margin:0 !important;
  text-decoration:none !important;
  box-shadow:none !important;
  -webkit-appearance:none !important;
  appearance:none !important;
  user-select:none !important;
  -webkit-tap-highlight-color:transparent !important;
  transition:background .2s !important
}
.counter-btn:hover{background:var(--primary-dark) !important}
.counter-btn:active{transform:scale(.92)}
.counter-btn:disabled{
  background:#cbd5e1 !important;
  cursor:not-allowed !important;
  opacity:.6 !important
}
.counter-input{
  flex:1 !important;
  border:none !important;
  background:transparent !important;
  text-align:center !important;
  font-size:14px !important;
  font-weight:700 !important;
  color:var(--text-dark) !important;
  width:auto !important;
  padding:0 !important;
  margin:0 !important;
  outline:none !important;
  box-shadow:none !important;
  min-width:0 !important;
  -moz-appearance:textfield !important;
  font-family:inherit !important;
  user-select:none !important
}
.counter-input::-webkit-outer-spin-button,
.counter-input::-webkit-inner-spin-button{-webkit-appearance:none;margin:0}
.counter-input:focus{outline:none !important;box-shadow:none !important;background:transparent !important}

.summary{background:var(--bg-soft);border-radius:8px;padding:12px;margin:12px 0}
.summary-row{display:flex;justify-content:space-between;font-size:12px;padding:3px 0;
  color:var(--text-muted)}
.summary-row.total{border-top:1px dashed var(--border);margin-top:7px;padding-top:9px;
  font-weight:700;color:var(--primary);font-size:15px}

.btn-book{width:100%;padding:13px;background:linear-gradient(135deg,var(--accent),#e89512);
  color:#fff;border:none;border-radius:8px;font-size:13px;font-weight:600;cursor:pointer;
  transition:all .25s;display:flex;align-items:center;justify-content:center;gap:8px;
  text-transform:uppercase;letter-spacing:.5px;font-family:inherit}
.btn-book:hover:not(:disabled){transform:translateY(-2px);box-shadow:0 8px 20px rgba(245,166,35,.4)}
.btn-book:disabled{opacity:.7;cursor:wait;transform:none}

.form-status{margin-top:10px;padding:10px;border-radius:7px;font-size:12px;text-align:center;display:none}
.form-status.success{display:block;background:#dcfce7;color:#166534;border:1px solid #86efac}
.form-status.error{display:block;background:#fee2e2;color:#991b1b;border:1px solid #fca5a5}

.trust-badges{display:flex;justify-content:space-around;padding:13px 0 0;margin-top:13px;
  border-top:1px solid var(--border)}
.trust-item{text-align:center;font-size:10px;color:var(--text-muted)}
.trust-item i{display:block;font-size:17px;color:var(--primary);margin-bottom:3px}

.contact-card{background:#fff;border-radius:12px;padding:16px;margin-top:14px;
  box-shadow:var(--shadow-sm);text-align:center;border:1px solid var(--border)}
.contact-card h4{font-size:12px;color:var(--text-muted);margin-bottom:7px;font-weight:500}
.contact-phone{font-family:'Playfair Display',serif;font-size:19px;color:var(--primary);
  font-weight:700;margin-bottom:9px}
.contact-actions{display:flex;gap:7px}
.contact-btn{flex:1;padding:8px;border-radius:6px;font-size:11px;font-weight:600;
  text-decoration:none;display:flex;align-items:center;justify-content:center;gap:6px;
  transition:all .2s;border:1px solid var(--border);color:var(--text-dark);background:#fafbfd}
.contact-btn.whatsapp{background:#25D366;color:#fff;border-color:#25D366}
.contact-btn:hover{transform:translateY(-1px)}

/* Related Tours */
.related-section{padding:40px 0 20px;background:#fff;margin-top:30px;border-top:1px solid var(--border)}
.related-header{text-align:center;margin-bottom:28px}
.related-header h2{font-family:'Playfair Display',serif;font-size:28px;color:var(--primary);
  margin-bottom:8px}
.related-header p{color:var(--text-muted);font-size:13px}
.related-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}
.related-card{background:#fff;border:1px solid var(--border);border-radius:12px;overflow:hidden;
  transition:all .3s;cursor:pointer}
.related-card:hover{transform:translateY(-4px);box-shadow:var(--shadow-lg);border-color:var(--primary-light)}
.related-img{height:180px;position:relative;overflow:hidden;background:var(--bg-soft)}
.related-img img{width:100%;height:100%;object-fit:cover;transition:transform .5s;display:block}
.related-card:hover .related-img img{transform:scale(1.08)}
.related-img::after{content:'';position:absolute;inset:0;background:linear-gradient(to top,rgba(26,58,110,.6),transparent 50%);pointer-events:none}
.related-duration{position:absolute;top:10px;right:10px;background:var(--accent);color:#fff;
