/* Modal */
.modal-overlay{position:fixed;inset:0;background:rgba(26,43,74,.7);backdrop-filter:blur(4px);
  z-index:99999;display:none;align-items:center;justify-content:center;padding:20px}
.modal-overlay.active{display:flex}
.modal{background:#fff;border-radius:14px;max-width:420px;width:100%;padding:26px;
  text-align:center;animation:modalIn .3s ease}
@keyframes modalIn{from{opacity:0;transform:scale(.95)}to{opacity:1;transform:scale(1)}}
.modal-icon{width:60px;height:60px;border-radius:50%;background:linear-gradient(135deg,#22c55e,#16a34a);
  color:#fff;display:flex;align-items:center;justify-content:center;font-size:24px;margin:0 auto 14px}
.modal h3{font-family:'Playfair Display',serif;color:var(--primary);font-size:21px;margin-bottom:8px}
.modal p{color:var(--text-muted);font-size:13px;margin-bottom:18px}
.modal-close{padding:10px 24px;background:var(--primary);color:#fff;border:none;border-radius:8px;
  font-size:13px;font-weight:600;cursor:pointer;font-family:inherit}

