.bk-hero h1{margin:0 0 16px;color:#1A3A6E;font-family:'Playfair Display',serif;font-size:42px;line-height:1.12;font-weight:700;max-width:1000px}
.bk-chips{display:flex;flex-wrap:wrap;gap:10px;margin:0 0 22px}
.bk-chip{display:inline-flex;align-items:center;gap:9px;background:#fff;border:1px solid #E1E8F0;border-radius:999px;padding:9px 16px;font-size:13.5px;font-weight:700;color:#172743;box-shadow:0 2px 8px rgba(26,58,110,.06)}
.bk-chip i{color:#1A3A6E;background:#F4F8FC;border-radius:50%;width:26px;height:26px;display:inline-flex;align-items:center;justify-content:center;font-size:12px}
.bk-gallery{display:grid;grid-template-columns:2fr 1fr;grid-template-rows:247px 247px;gap:10px;margin:0 auto 38px}
.bk-main{grid-row:1/3;border-radius:16px;overflow:hidden;background:#dfe8f2;cursor:zoom-in;position:relative}
.bk-tile{border-radius:16px;overflow:hidden;background:#dfe8f2;cursor:zoom-in;position:relative}
.bk-gallery img{width:100%;height:100%;object-fit:cover;display:block;transition:transform .5s cubic-bezier(.22,.61,.36,1)}
.bk-main:hover img,.bk-tile:hover img{transform:scale(1.05)}
.bk-more-chip{position:absolute;right:14px;bottom:14px;display:inline-flex;align-items:center;gap:8px;background:rgba(13,29,54,.82);color:#fff;border-radius:999px;padding:9px 16px;font-size:13px;font-weight:700;-webkit-backdrop-filter:blur(6px);backdrop-filter:blur(6px)}
.bk-more-chip i{color:#F5A623}
@media(max-width:992px){.bk-hero h1{font-size:32px}}
@media(max-width:860px){
  .bk-gallery{grid-template-columns:1fr 1fr;grid-template-rows:220px 130px}
  .bk-main{grid-column:1/3;grid-row:auto}
  .bk-tile{grid-row:auto}
}
@media(max-width:640px){
  .bk-hero{padding-top:18px}
  .bk-hero h1{font-size:25px;line-height:1.2}
  .bk-chips{gap:8px;margin-bottom:18px}
  .bk-chip{font-size:12.5px;padding:7px 12px}
  .bk-chip i{width:22px;height:22px;font-size:11px}
  .bk-gallery{grid-template-rows:200px 96px;gap:8px;margin-bottom:28px}
  .bk-main,.bk-tile{border-radius:12px}
  .bk-more-chip{font-size:11.5px;padding:7px 12px}
}
/* ── lightbox ── */
.bk-lb{position:fixed;inset:0;z-index:999999;background:rgba(9,20,38,.94);display:none;align-items:center;justify-content:center}
.bk-lb.open{display:flex}
.bk-lb img{max-width:88vw;max-height:82vh;border-radius:10px;box-shadow:0 30px 80px rgba(0,0,0,.5)}
.bk-lb-close{position:absolute;top:18px;right:22px;width:44px;height:44px;border-radius:50%;background:rgba(255,255,255,.12);border:0;color:#fff;font-size:20px;cursor:pointer}
.bk-lb-close:hover{background:rgba(255,255,255,.25)}
.bk-lb-arrow{position:absolute;top:50%;transform:translateY(-50%);width:52px;height:52px;border-radius:50%;background:rgba(255,255,255,.12);border:0;color:#fff;font-size:18px;cursor:pointer}
.bk-lb-arrow:hover{background:#F5A623;color:#10233D}
.bk-lb-prev{left:22px}.bk-lb-next{right:22px}
.bk-lb-count{position:absolute;bottom:22px;left:50%;transform:translateX(-50%);color:rgba(255,255,255,.85);font-size:13px;font-weight:700;letter-spacing:1px}
</style>
<div class="bk-lb" id="bkLb">
  <button class="bk-lb-close" aria-label="Close">✕</button>
  <button class="bk-lb-prev" aria-label="Previous">‹</button>
  <img decoding="async" src="/assets/uploads/2026/07/Ancient-Wonders-Of-Giza-Saqqara-scaled-1.jpg" alt="Saqqara, Memphis &amp; Dahshur Day Trip from Cairo">
  <button class="bk-lb-next" aria-label="Next">›</button>
  <div class="bk-lb-count">1 / 3</div>
</div>

<script>
(function(){
  var lb=document.getElementById('bkLb');if(!lb)return;
  var imgs=[].slice.call(document.querySelectorAll('.bk-gallery img'));
  var cur=0,img=lb.querySelector('img'),cnt=lb.querySelector('.bk-lb-count');
  function show(i){cur=(i+imgs.length)%imgs.length;img.src=imgs[cur].getAttribute('src');cnt.textContent=(cur+1)+' / '+imgs.length;}
  function open(i){show(i);lb.classList.add('open');document.body.style.overflow='hidden';}
  function close(){lb.classList.remove('open');document.body.style.overflow='';}
  imgs.forEach(function(im,i){im.style.cursor='zoom-in';im.addEventListener('click',function(){open(i);});});
  lb.querySelector('.bk-lb-close').addEventListener('click',close);
  lb.querySelector('.bk-lb-prev').addEventListener('click',function(e){e.stopPropagation();show(cur-1);});
  lb.querySelector('.bk-lb-next').addEventListener('click',function(e){e.stopPropagation();show(cur+1);});
  lb.addEventListener('click',function(e){if(e.target===lb)close();});
  document.addEventListener('keydown',function(e){
    if(!lb.classList.contains('open'))return;
    if(e.key==='Escape')close();
    if(e.key==='ArrowLeft')show(cur-1);
    if(e.key==='ArrowRight')show(cur+1);
  });
})();
</script>

