  <div class="modal">
    <div class="modal-icon"><i class="fas fa-check"></i></div>
    <h3>Booking Request Sent!</h3>
    <p>Thank you for choosing us. Our team will contact you within 24 hours to confirm your reservation and answer any questions.</p>
    <button class="modal-close" id="modalCloseBtn">Got it</button>
  </div>
